INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(6350, 'supply shock', '/səˈplaɪ ʃɒk/', 'noun', '{"zh-TW":["供給衝擊"],"en":["a sudden change in supply that dramatically affects the price of a good or service"]}', NULL, 'negative supply shock / positive supply shock / supply shock inflation', '[{"en":"The oil embargo caused a severe negative supply shock that triggered global inflation.","zh-TW":"石油禁運造成了嚴重的負面供給衝擊，引發了全球通膨。"},{"en":"New technology can create a positive supply shock by dramatically reducing production costs.","zh-TW":"新技術可以通過大幅降低生產成本來創造正面供給衝擊。"}]', NULL, NULL, 4, 6350, NULL),
(6351, 'supply-demand balance', '/səˈplaɪ dɪˈmɑːnd ˈbæləns/', 'noun', '{"zh-TW":["供需平衡"],"en":["the equilibrium between the amount of a good produced and consumer demand"]}', NULL, 'maintain supply-demand balance / disrupt the supply-demand balance', '[{"en":"Rising raw material costs disturbed the supply-demand balance.","zh-TW":"原材料成本上漲擾亂了供需平衡。"},{"en":"Market prices adjust automatically to restore supply-demand balance.","zh-TW":"市場價格自動調整以恢復供需平衡。"}]', NULL, NULL, 5, 6351, NULL),
(6352, 'supply-side economics', '/səˈplaɪ saɪd ˌiːkəˈnɒmɪks/', 'noun', '{"zh-TW":["供給側經濟學"],"en":["economic theory that tax cuts and deregulation stimulate growth by boosting supply"]}', NULL, 'adopt supply-side economics / supply-side economics policy / critique of supply-side economics', '[{"en":"Supply-side economics argues that lowering corporate taxes boosts investment.","zh-TW":"供給側經濟學認為降低企業稅可以促進投資。"},{"en":"Critics argue that supply-side economics mainly benefits the wealthy.","zh-TW":"批評者認為供給側經濟學主要使富人受益。"}]', NULL, NULL, 5, 6352, NULL),
(6353, 'support', '/səˈpɔːrt/', 'noun, verb', '{"zh-TW":["支持；支援","支持；贊助"],"en":["help or encouragement","to give assistance to"]}', NULL, 'customer support / technical support / support a proposal', '[{"en":"The proposal received strong support from management.","zh-TW":"該提案獲得了管理層的大力支持。"},{"en":"We provide 24/7 customer support.","zh-TW":"我們提供全天候客戶支援。"}]', '{"noun":"support, supporter","verb":"support","adjective":"supportive"}', NULL, 3, 6353, 225),
(6354, 'suppose', '/səˈpoʊz/', 'verb', '{"zh-TW":["假設；認為"],"en":["to assume; to believe"]}', NULL, 'be supposed to / I suppose / suppose that', '[{"en":"You are supposed to submit the form by today.","zh-TW":"你應該在今天之前提交表格。"},{"en":"I suppose we could try a different approach.","zh-TW":"我想我們可以嘗試不同的方法。"}]', '{"noun":"supposition","verb":"suppose","adjective":"supposed"}', NULL, 3, 6354, NULL),
(6355, 'suppress', '/səˈpres/', 'verb', '{"zh-TW":["壓制；抑制"],"en":["to prevent from being expressed or known"]}', NULL, 'suppress information / suppress competition / suppress dissent', '[{"en":"The company tried to suppress negative reviews.","zh-TW":"公司試圖壓制負面評論。"},{"en":"Rising interest rates suppressed consumer spending.","zh-TW":"利率上升抑制了消費支出。"}]', '{"noun":"suppression","verb":"suppress"}', NULL, 3, 6355, NULL),
(6356, 'sure', '/ʃʊr/', 'adjective', '{"zh-TW":["確定的；當然"],"en":["certain; confident"]}', NULL, 'make sure / for sure', '[{"en":"Make sure you save the file.","zh-TW":"確保你儲存了檔案。"},{"en":"We will finish on time for sure.","zh-TW":"我們肯定會準時完成。"}]', '{"adjective":"sure","adverb":"surely"}', NULL, 1, 6356, NULL),
(6357, 'surety', '/ˈʃʊərɪti/', 'noun', '{"zh-TW":["保證人；保證金；擔保"],"en":["a formal guarantee or pledge; a person who takes responsibility for another''s obligation"]}', NULL, 'act as surety / provide surety / surety bond', '[{"en":"The defendant was released on bail after a surety was provided by a family member.","zh-TW":"在家庭成員提供擔保後，被告以保釋金釋放。"},{"en":"A surety bond protects clients against contractor default on a construction project.","zh-TW":"保證金保護客戶免受建設項目中承包商違約的影響。"}]', NULL, NULL, 2, 6357, NULL),
(6358, 'surge', '/sɜːrdʒ/', 'noun, verb', '{"zh-TW":["激增；猛漲","急增；湧現"],"en":["a sudden large increase","to increase suddenly"]}', NULL, 'surge in demand / price surge / power surge', '[{"en":"There was a surge in online orders during the holiday.","zh-TW":"假期期間線上訂單激增。"},{"en":"Oil prices surged after the announcement.","zh-TW":"公告後油價猛漲。"}]', '{"noun":"surge","verb":"surge"}', NULL, 2, 6358, NULL),
(6359, 'surgery', '/ˈsɜːrdʒəri/', 'noun', '{"zh-TW":["手術；外科手術"],"en":["a medical operation to treat a physical condition"]}', NULL, 'undergo surgery / elective surgery', '[{"en":"The patient underwent surgery to remove the tumor.","zh-TW":"病患接受了手術以切除腫瘤。"},{"en":"Recovery from surgery may take several weeks.","zh-TW":"手術後的康復可能需要幾週時間。"}]', '{"verb":"operate","adjective":"surgical"}', NULL, 3, 6359, NULL),
(6360, 'surpass', '/sərˈpæs/', 'verb', '{"zh-TW":["超越；勝過"],"en":["to exceed or be better than"]}', NULL, 'surpass expectations / surpass a record / surpass competitors', '[{"en":"Sales surpassed expectations by 20%.","zh-TW":"銷售額超出預期20%。"},{"en":"The company surpassed its competitors in revenue.","zh-TW":"該公司在營收上超越了競爭對手。"}]', '{"verb":"surpass"}', NULL, 3, 6360, NULL),
(6361, 'surplus', '/ˈsɜːrpləs/', 'noun, adjective', '{"zh-TW":["剩餘；盈餘","多餘的"],"en":["an amount left over","more than what is needed"]}', NULL, 'budget surplus / trade surplus / surplus inventory', '[{"en":"The government reported a budget surplus.","zh-TW":"政府報告了預算盈餘。"},{"en":"Surplus inventory was sold at a discount.","zh-TW":"多餘的庫存以折扣價出售。"}]', '{"noun":"surplus","adjective":"surplus"}', NULL, 3, 6361, 939),
(6362, 'surplus cash', '/ˈsɜːrpləs kæʃ/', 'noun', '{"zh-TW":["盈餘現金"],"en":["cash available after meeting all operational and financial obligations"]}', NULL, 'deploy surplus cash / invest surplus cash', '[{"en":"The company invested surplus cash in short-term government bonds.","zh-TW":"公司將盈餘現金投資於短期政府債券。"},{"en":"Surplus cash can be returned to shareholders through dividends or buybacks.","zh-TW":"盈餘現金可以通過股息或回購的形式返還給股東。"}]', NULL, NULL, 4, 6362, NULL),
(6363, 'surplus inventory', '/ˈsɜːrpləs ˈɪnvəntəri/', 'noun', '{"zh-TW":["庫存積壓；過剩庫存"],"en":["inventory exceeding current demand that must be managed or liquidated"]}', NULL, 'reduce surplus inventory / surplus inventory sale', '[{"en":"The company launched a clearance sale to reduce surplus inventory.","zh-TW":"公司啟動了清倉銷售以減少庫存積壓。"},{"en":"Surplus inventory ties up working capital and increases storage costs.","zh-TW":"過剩庫存佔用了營運資金並增加了存儲成本。"}]', NULL, NULL, 5, 6363, NULL),
(6364, 'surplus value', '/ˈsɜːpləs ˈvæljuː/', 'noun', '{"zh-TW":["剩餘價值"],"en":["in Marxist theory, the excess of a worker''s output over what they are paid"]}', NULL, 'create surplus value / extract surplus value / concept of surplus value', '[{"en":"Marx argued that capitalists profit by extracting surplus value from workers'' labor.","zh-TW":"馬克思認為，資本家通過從工人的勞動中提取剩餘價值來獲利。"},{"en":"The theory of surplus value highlights the relationship between labor and capital.","zh-TW":"剩餘價值理論強調了勞動與資本之間的關係。"}]', NULL, NULL, 5, 6364, NULL),
(6365, 'surprise', '/sərˈpraɪz/', 'noun', '{"zh-TW":["驚喜；意外"],"en":["an unexpected event"]}', NULL, 'come as a surprise / surprise visit', '[{"en":"The announcement came as no surprise.","zh-TW":"這個公告並不令人意外。"},{"en":"The CEO made a surprise visit.","zh-TW":"執行長進行了突擊訪視。"}]', '{"noun":"surprise","verb":"surprise","adjective":"surprising","adverb":"surprisingly"}', NULL, 3, 6365, NULL),
(6366, 'surveillance', '/sɜːrˈveɪləns/', 'noun', '{"zh-TW":["監控；監視"],"en":["close observation of a person or place"]}', NULL, 'under surveillance / surveillance camera / surveillance system', '[{"en":"The building is equipped with surveillance cameras.","zh-TW":"這棟建築配有監視攝影機。"},{"en":"The suspect was placed under surveillance.","zh-TW":"嫌疑人被置於監控之下。"}]', '{"noun":"surveillance","verb":"surveil"}', NULL, 4, 6366, NULL),
(6367, 'survey', '/ˈsɜːrveɪ/', 'noun, verb', '{"zh-TW":["調查；問卷","進行調查"],"en":["a study of opinions or conditions","to investigate"]}', NULL, 'conduct a survey / customer survey / survey results', '[{"en":"We conducted a customer satisfaction survey.","zh-TW":"我們進行了客戶滿意度調查。"},{"en":"The survey revealed key market trends.","zh-TW":"調查揭示了主要的市場趨勢。"}]', '{"noun":"survey, surveyor","verb":"survey"}', NULL, 2, 6367, 226),
(6368, 'survive', '/sərˈvaɪv/', 'verb', '{"zh-TW":["存活；度過","倖存"],"en":["to continue to live or exist"]}', NULL, 'survive a crisis / survival rate / survive competition', '[{"en":"Few small businesses survive beyond five years.","zh-TW":"很少有小企業能存活超過五年。"},{"en":"The company survived the economic downturn.","zh-TW":"這家公司撐過了經濟衰退。"}]', '{"noun":"survival, survivor","verb":"survive"}', NULL, 3, 6368, NULL),
(6369, 'susceptible', '/səˈseptəbl/', 'adjective', '{"zh-TW":["易受影響的；敏感的"],"en":["likely to be affected by something"]}', NULL, 'susceptible to / highly susceptible / susceptible to change', '[{"en":"The market is susceptible to sudden changes.","zh-TW":"市場容易受到突然變化的影響。"},{"en":"Older systems are more susceptible to cyber attacks.","zh-TW":"較舊的系統更容易受到網路攻擊。"}]', '{"noun":"susceptibility","adjective":"susceptible"}', NULL, 4, 6369, NULL),
(6370, 'suspect', '/səˈspekt/', 'verb, noun', '{"zh-TW":["懷疑；猜想","嫌疑犯"],"en":["to believe something is likely","a person thought to be guilty"]}', NULL, 'suspect fraud / suspect that / prime suspect', '[{"en":"Auditors suspect financial irregularities.","zh-TW":"審計員懷疑有財務違規行為。"},{"en":"I suspect the delay is due to supply issues.","zh-TW":"我懷疑延遲是由於供應問題。"}]', '{"noun":"suspect, suspicion","verb":"suspect","adjective":"suspicious, suspected"}', NULL, 3, 6370, NULL),
(6371, 'suspend', '/səˈspend/', 'verb', '{"zh-TW":["暫停；中止","懸掛"],"en":["to temporarily stop","to hang from above"]}', NULL, 'suspend operations / suspend trading / suspend an employee', '[{"en":"The company suspended trading of its shares.","zh-TW":"公司暫停了股票交易。"},{"en":"Operations were suspended due to safety concerns.","zh-TW":"因安全顧慮，營運已暫停。"}]', '{"noun":"suspension","verb":"suspend"}', NULL, 3, 6371, NULL),
(6372, 'suspension', '/səˈspɛnʃən/', 'noun', '{"zh-TW":["暫停；停職；中止"],"en":["the temporary stopping of something"]}', NULL, 'suspension of services / suspension without pay', '[{"en":"The employee received a suspension pending the investigation.","zh-TW":"員工在等待調查期間被暫停職務。"},{"en":"Service suspension was announced due to maintenance.","zh-TW":"由於維護工作，服務暫停已被宣布。"}]', '{"verb":"suspend","adjective":"suspended"}', NULL, 4, 6372, NULL),
(6373, 'sustain', '/səˈsteɪn/', 'verb', '{"zh-TW":["維持；承受","維持；持續","承受"],"en":["to maintain at a certain level","to suffer or experience","to maintain over time","to suffer or endure"]}', '{"prefix":{"text":"sus-","meaning":"under (從下)"},"root":{"text":"tain","meaning":"hold (持有)"},"logic":"從下方支撐持住，即「維持」。"}', 'sustain growth / sustain an injury / sustainable development; sustain growth / sustain losses / sustainable development', '[{"en":"The economy cannot sustain this level of spending.","zh-TW":"經濟無法維持這種支出水平。"},{"en":"He sustained minor injuries in the accident.","zh-TW":"他在事故中受了輕傷。"},{"en":"The business needs to sustain profitability.","zh-TW":"企業需要維持盈利能力。"},{"en":"The company sustained heavy losses last year.","zh-TW":"公司去年蒙受了重大損失。"}]', '{"adjective":"sustainable","noun":"sustainability","verb":"sustain"}', NULL, 3, 6373, 227),
(6374, 'sustainability', '/səˌsteɪnəˈbɪlɪti/', 'noun', '{"zh-TW":["可持續性；永續性"],"en":["meeting current needs without compromising future needs"]}', NULL, 'corporate sustainability / sustainability report / sustainability goals', '[{"en":"The company published its first sustainability report.","zh-TW":"公司發布了第一份永續報告。"},{"en":"Sustainability is now a core pillar of our strategy.","zh-TW":"永續性現在是我們策略的核心支柱。"}]', '{"adjective":"sustainable","adverb":"sustainably"}', NULL, 5, 6374, 625),
(6375, 'sustainability report', '/səˌsteɪnəˈbɪlɪti rɪˈpɔːrt/', 'noun', '{"zh-TW":["可持續發展報告"],"en":["a public document outlining an organization environmental and social impact"]}', NULL, 'publish a sustainability report / sustainability report metrics', '[{"en":"The company''s sustainability report highlighted its carbon reduction goals.","zh-TW":"公司的可持續發展報告強調了其碳減排目標。"},{"en":"Investors increasingly consider sustainability reports when making decisions.","zh-TW":"投資者在決策時越來越考慮可持續發展報告。"}]', NULL, NULL, 5, 6375, NULL),
(6376, 'sustainability reporting', '/səˌsteɪnəˈbɪlɪti rɪˈpɔːrtɪŋ/', 'noun', '{"zh-TW":["永續報告"],"en":["the disclosure of an organization''s environmental, social, and governance performance"]}', NULL, 'publish sustainability reporting / sustainability reporting framework / improve sustainability reporting', '[{"en":"Investors increasingly require sustainability reporting from portfolio companies.","zh-TW":"投資者越來越要求投資組合公司提供永續報告。"},{"en":"Sustainability reporting helps companies identify and manage ESG risks.","zh-TW":"永續報告幫助公司識別和管理ESG風險。"}]', NULL, NULL, 5, 6376, NULL),
(6377, 'sustainable', '/səˈsteɪnəbl/', 'adjective', '{"zh-TW":["可持續的；永續的"],"en":["able to be maintained over the long term without depleting resources"]}', NULL, 'sustainable growth / sustainable business / sustainable practices', '[{"en":"The company shifted to sustainable packaging to reduce waste.","zh-TW":"公司轉向可持續包裝以減少廢物。"},{"en":"Sustainable growth requires balancing short-term gains with long-term health.","zh-TW":"可持續增長需要平衡短期收益和長期健康。"}]', '{"adverb":"sustainably","noun":"sustainability"}', NULL, 4, 6377, 466),
(6378, 'sustainable development', '/səˈsteɪnəbəl dɪˈvɛləpmənt/', 'noun', '{"zh-TW":["永續發展"],"en":["development that meets present needs without compromising the future"]}', NULL, 'promote sustainable development / sustainable development goal', '[{"en":"The UN''s sustainable development goals guide global policy.","zh-TW":"聯合國的永續發展目標指導全球政策。"},{"en":"Sustainable development balances economic growth with environmental care.","zh-TW":"永續發展平衡了經濟增長與環境保護。"}]', '{"verb":"sustain","adjective":"sustainable"}', NULL, 5, 6378, NULL),
(6379, 'sustainable finance', '/səˈsteɪnəbəl ˈfaɪnæns/', 'noun', '{"zh-TW":["可持續金融；綠色金融"],"en":["financial services that incorporate environmental, social, and governance criteria"]}', NULL, 'develop sustainable finance / sustainable finance framework / sustainable finance products', '[{"en":"Sustainable finance channels capital toward projects that address climate change.","zh-TW":"可持續金融將資本引導到應對氣候變化的項目上。"},{"en":"Central banks are integrating sustainable finance considerations into regulatory frameworks.","zh-TW":"各中央銀行正在將可持續金融考量納入監管框架。"}]', NULL, NULL, 5, 6379, NULL),
(6380, 'sustainable food', '/''səˌsteɪnəbəl fuːd/', 'noun', '{"zh-TW":["永續食物；可持續食品"],"en":["food produced in a way that does not deplete natural resources or harm the environment"]}', NULL, 'promote sustainable food / sustainable food system / choose sustainable food', '[{"en":"Schools are encouraging students to choose sustainable food options to reduce environmental impact.","zh-TW":"學校正在鼓勵學生選擇永續食物選項以減少環境影響。"},{"en":"Sustainable food production requires careful management of land, water, and energy resources.","zh-TW":"永續食品生產需要對土地、水和能源資源進行謹慎管理。"}]', NULL, NULL, 5, 6380, NULL),
(6381, 'sustainable procurement', '/səˈsteɪnəbəl prəˈkjʊərmənt/', 'noun', '{"zh-TW":["永續採購；可持續採購"],"en":["purchasing goods and services in a way that minimizes environmental and social impact"]}', NULL, 'adopt sustainable procurement / sustainable procurement policy', '[{"en":"The company''s sustainable procurement policy favors eco-certified suppliers.","zh-TW":"公司的永續採購政策優先考慮環保認證供應商。"},{"en":"Sustainable procurement reduces carbon footprint across the supply chain.","zh-TW":"永續採購降低了整個供應鏈的碳足跡。"}]', NULL, NULL, 5, 6381, NULL),
(6382, 'sustainable sourcing', '/səˈsteɪnəbəl ˈsɔːrsɪŋ/', 'noun', '{"zh-TW":["永續採購"],"en":["obtaining materials with minimal environmental impact"]}', NULL, 'practice sustainable sourcing / sustainable sourcing policy', '[{"en":"The company adopted a sustainable sourcing policy for all suppliers.","zh-TW":"公司對所有供應商採用了永續採購政策。"},{"en":"Sustainable sourcing helps preserve natural resources.","zh-TW":"永續採購有助於保護自然資源。"}]', NULL, NULL, 5, 6382, NULL),
(6383, 'swap', '/swɒp/', 'noun', '{"zh-TW":["互換合約；掉期"],"en":["a derivative contract exchanging cash flows between two parties"]}', NULL, 'interest rate swap / currency swap / credit default swap', '[{"en":"The company entered an interest rate swap to fix borrowing costs.","zh-TW":"公司簽訂了利率互換合約以固定借貸成本。"},{"en":"Currency swaps help companies manage foreign exchange risk.","zh-TW":"貨幣互換幫助公司管理外匯風險。"}]', '{"verb":"swap"}', NULL, 1, 6383, NULL),
(6384, 'swap agreement', '/swɒp əˈɡriːmənt/', 'noun', '{"zh-TW":["互換協議"],"en":["a contract where two parties agree to exchange cash flows or other financial instruments"]}', NULL, 'enter a swap agreement / swap agreement terms', '[{"en":"The company entered a swap agreement to convert variable to fixed interest.","zh-TW":"公司簽訂了互換協議將浮動利率轉換為固定利率。"},{"en":"Swap agreements are commonly used to manage currency and interest rate risk.","zh-TW":"互換協議常用於管理貨幣和利率風險。"}]', NULL, NULL, 5, 6384, NULL),
(6385, 'sweep account', '/swiːp əˈkaʊnt/', 'noun', '{"zh-TW":["掃描帳戶；自動轉帳帳戶"],"en":["an account that automatically moves funds to a higher-yield vehicle at the end of each day"]}', NULL, 'set up a sweep account / corporate sweep account / sweep account feature', '[{"en":"The company uses a sweep account to maximize interest earnings on idle cash.","zh-TW":"公司使用掃描帳戶最大化閒置現金的利息收益。"},{"en":"Sweep accounts are a common cash management tool for corporations.","zh-TW":"掃描帳戶是企業常見的現金管理工具。"}]', NULL, NULL, 5, 6385, NULL),
(6386, 'sweet', '/swiːt/', 'adjective', '{"zh-TW":["甜的；親切的"],"en":["having the taste of sugar","kind and pleasant"]}', NULL, 'sweet spot / sweet deal', '[{"en":"We found the sweet spot for pricing.","zh-TW":"我們找到了定價的最佳點。"},{"en":"That is a sweet deal for both parties.","zh-TW":"對雙方來說都是很棒的交易。"}]', '{"adjective":"sweet","noun":"sweetness","adverb":"sweetly","verb":"sweeten"}', NULL, 2, 6386, NULL),
(6387, 'sweetener', '/''swiːtənər/', 'noun', '{"zh-TW":["甜味劑；增甜劑"],"en":["a substance used as a substitute for sugar to add sweetness without calories"]}', NULL, 'artificial sweetener / natural sweetener / add a sweetener', '[{"en":"She used a natural sweetener like honey instead of refined sugar.","zh-TW":"她使用天然甜味劑如蜂蜜，而不是精製糖。"},{"en":"Artificial sweeteners are widely used in diet beverages and low-calorie foods.","zh-TW":"人工甜味劑被廣泛用於低熱量飲料和低卡路里食品。"}]', '{"verb":"sweeten"}', NULL, 3, 6387, NULL),
(6388, 'swimming pool', '/''swɪmɪŋ puːl/', 'noun', '{"zh-TW":["游泳池"],"en":["an artificial pool of water constructed for swimming"]}', NULL, 'public swimming pool / indoor swimming pool / competitive swimming pool', '[{"en":"She swims fifty laps in the swimming pool every morning before work.","zh-TW":"她每天早上上班前在游泳池游五十個來回。"},{"en":"The school opened a new indoor swimming pool for use by students and the community.","zh-TW":"學校為學生和社區開放了一個新的室內游泳池。"}]', NULL, NULL, 5, 6388, NULL),
(6389, 'switch', '/swɪtʃ/', 'noun, verb', '{"zh-TW":["轉換；開關","切換；轉變"],"en":["a change; a device for making connections","to change from one thing to another"]}', NULL, 'switch to / make the switch / switch providers', '[{"en":"Many companies switched to remote work.","zh-TW":"許多公司轉換為遠端工作。"},{"en":"Customers can switch providers without penalty.","zh-TW":"客戶可以無需罰款更換供應商。"}]', '{"noun":"switch","verb":"switch"}', NULL, 2, 6389, NULL),
(6390, 'SWOT analysis', '/swɒt əˈnælɪsɪs/', 'noun', '{"zh-TW":["SWOT分析"],"en":["a framework examining Strengths, Weaknesses, Opportunities, and Threats"]}', NULL, 'conduct a SWOT analysis / SWOT analysis results / present SWOT analysis', '[{"en":"The SWOT analysis highlighted the company''s strong brand as a key strength.","zh-TW":"SWOT分析強調了公司強大品牌作為關鍵優勢。"},{"en":"SWOT analysis informed the board''s strategic planning session.","zh-TW":"SWOT分析為董事會的策略規劃會議提供了依據。"}]', NULL, NULL, 5, 6390, NULL),
(6391, 'syllabus', '/ˈsɪləbəs/', 'noun', '{"zh-TW":["課程大綱","教學大綱"],"en":["an outline of subjects in a course","a document showing what will be taught in a course"]}', NULL, 'course syllabus / follow the syllabus; course syllabus / on the syllabus', '[{"en":"The training syllabus is updated annually.","zh-TW":"培訓大綱每年更新。"},{"en":"Please review the syllabus before the course begins.","zh-TW":"請在課程開始前閱讀課程大綱。"},{"en":"Check the syllabus for due dates.","zh-TW":"查看教學大綱上的截止日期。"},{"en":"The syllabus outlines all assignments.","zh-TW":"教學大綱列出了所有作業。"}]', '{"noun":"syllabus"}', NULL, 3, 6391, NULL),
(6392, 'symbol', '/ˈsɪmbl/', 'noun', '{"zh-TW":["符號；象徵"],"en":["something that represents something else"]}', NULL, 'symbol of / stock symbol / status symbol', '[{"en":"The logo is a symbol of quality and trust.","zh-TW":"這個標誌是品質和信任的象徵。"},{"en":"Check the stock symbol before placing an order.","zh-TW":"下單前請確認股票代碼。"}]', '{"noun":"symbol, symbolism","verb":"symbolize","adjective":"symbolic"}', NULL, 2, 6392, NULL),
(6393, 'sympathetic', '/ˌsɪmpəˈθetɪk/', 'adjective', '{"zh-TW":["同情的；有同感的"],"en":["feeling or showing concern for someone''s misfortune"]}', '{"prefix":{"text":"sym-","meaning":"together (一起)"},"root":{"text":"path","meaning":"feeling (感受)"},"suffix":{"text":"-etic","meaning":"relating to (相關的)"},"logic":"一起感受的，即「同情的」。"}', 'sympathetic to / sympathetic ear', '[{"en":"She was sympathetic to his problems.","zh-TW":"她對他的問題表示同情。"},{"en":"He found a sympathetic listener in his friend.","zh-TW":"他在朋友那裡找到了知心的傾聽者。"}]', '{"noun":"sympathy","verb":"sympathize"}', NULL, 4, 6393, NULL),
(6394, 'sympathy', '/ˈsɪmpəθi/', 'noun', '{"zh-TW":["同情；同感"],"en":["feelings of pity and sorrow for someone"]}', NULL, 'express sympathy / in sympathy with / earn sympathy', '[{"en":"We express our deepest sympathy for your loss.","zh-TW":"我們對您的損失表示最深切的同情。"},{"en":"Workers went on strike in sympathy with the fired employees.","zh-TW":"工人們為聲援被解雇的員工而罷工。"}]', '{"noun":"sympathy","adjective":"sympathetic","verb":"sympathize"}', NULL, 3, 6394, NULL),
(6395, 'symphony', '/ˈsɪmfəni/', 'noun', '{"zh-TW":["交響曲"],"en":["a long piece of music for a full orchestra"]}', '{"prefix":{"text":"sym-","meaning":"together (一起)"},"root":{"text":"phon","meaning":"sound (聲音)"},"suffix":{"text":"-y","meaning":"state (狀態)"},"logic":"聲音在一起和諧，即「交響曲」。"}', 'symphony orchestra / compose a symphony', '[{"en":"Beethoven''s Ninth Symphony is world-famous.","zh-TW":"貝多芬第九號交響曲舉世聞名。"},{"en":"We attended a symphony concert last night.","zh-TW":"我們昨晚參加了一場交響音樂會。"}]', '{"adjective":"symphonic"}', NULL, 3, 6395, NULL),
(6396, 'symptom', '/ˈsɪmptəm/', 'noun', '{"zh-TW":["症狀"],"en":["a sign of a disease or illness"]}', NULL, 'common symptom / report symptoms', '[{"en":"Tell your doctor about all your symptoms.","zh-TW":"將您的所有症狀告知醫生。"},{"en":"The most common symptoms include fever and fatigue.","zh-TW":"最常見的症狀包括發燒和疲勞。"}]', '{"adjective":"symptomatic"}', NULL, 3, 6396, NULL),
(6397, 'syndicate', '/ˈsɪndɪkɪt/', 'noun', '{"zh-TW":["辛迪加；聯合組織"],"en":["a group of individuals or organizations combined for a purpose"]}', NULL, 'banking syndicate / loan syndicate', '[{"en":"A banking syndicate financed the project.","zh-TW":"一個銀行聯合組織為專案提供了融資。"},{"en":"The loan was arranged through a syndicate.","zh-TW":"貸款透過聯貸組織安排。"}]', '{"noun":"syndicate","verb":"syndicate","noun2":"syndication"}', NULL, 3, 6397, NULL),
(6398, 'syndicated loan', '/ˈsɪndɪkeɪtɪd loʊn/', 'noun', '{"zh-TW":["聯合貸款；銀團貸款"],"en":["a large loan provided jointly by a group of lenders to a single borrower"]}', NULL, 'arrange a syndicated loan / syndicated loan facility', '[{"en":"The company raised $500 million through a syndicated loan from ten banks.","zh-TW":"公司通過來自十家銀行的聯合貸款籌集了5億元。"},{"en":"Syndicated loans spread credit risk among multiple lenders.","zh-TW":"聯合貸款在多個貸款方之間分散了信用風險。"}]', NULL, NULL, 5, 6398, NULL),
(6399, 'syndication', '/ˌsɪndɪˈkeɪʃən/', 'noun', '{"zh-TW":["辛迪加；聯合貸款；聯合融資"],"en":["the process of organizing a group of lenders or investors to fund a transaction"]}', NULL, 'loan syndication / bond syndication / syndication process', '[{"en":"The large loan was arranged through bank syndication.","zh-TW":"這筆大額貸款通過銀行聯合融資安排。"},{"en":"Syndication allows risk to be spread among multiple lenders.","zh-TW":"聯合融資允許風險分散在多個貸款方之間。"}]', '{"verb":"syndicate","adjective":"syndicated"}', NULL, 4, 6399, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(6400, 'synergize', '/ˈsɪnərdʒaɪz/', 'verb', '{"zh-TW":["協同運作；發揮協同效應"],"en":["to work together in a way that produces a combined effect greater than the parts"]}', NULL, 'synergize efforts / synergize teams', '[{"en":"The two departments synergized to deliver a stronger proposal.","zh-TW":"兩個部門協同運作，提交了更有力的提案。"},{"en":"Great teams synergize their diverse skills for better results.","zh-TW":"優秀的團隊協同發揮各自的多元技能以獲得更好的成果。"}]', '{"noun":"synergy","adjective":"synergistic"}', NULL, 3, 6400, NULL),
(6401, 'synergy', '/ˈsɪnədʒi/', 'noun', '{"zh-TW":["協同效應"],"en":["the combined benefit exceeding the sum of individual parts, often in mergers"]}', NULL, 'realize synergies / cost synergies / revenue synergies / merger synergies', '[{"en":"The merger was expected to generate $50 million in cost synergies.","zh-TW":"合併預計將產生5000萬美元的成本協同效應。"},{"en":"Synergies from the acquisition took two years to fully materialize.","zh-TW":"收購的協同效應花了兩年時間才完全實現。"}]', '{"adjective":"synergistic","verb":"synergize"}', NULL, 3, 6401, NULL),
(6402, 'synopsis', '/''sɪˌnɒpsɪs/', 'noun', '{"zh-TW":["摘要；概要；概述"],"en":["a brief summary of the major points of a subject or written work"]}', NULL, 'write a synopsis / read the synopsis / provide a synopsis', '[{"en":"She submitted a synopsis of the novel to the publisher before completing the full manuscript.","zh-TW":"她在完成完整手稿之前向出版商提交了小說的摘要。"},{"en":"The conference program included a synopsis of each speaker''s presentation.","zh-TW":"會議程序包括每位演講者演示文稿的概要。"}]', '{"verb":"summarize","adjective":"synoptic"}', NULL, 3, 6402, NULL),
(6403, 'syntax', '/ˈsɪntæks/', 'noun', '{"zh-TW":["語法；句法"],"en":["the rules governing the structure of a programming language"]}', NULL, 'syntax error / correct syntax / syntax highlighting', '[{"en":"A missing semicolon caused a syntax error in the program.","zh-TW":"缺少分號在程式中導致了語法錯誤。"},{"en":"Each programming language has its own syntax that must be learned.","zh-TW":"每種程式設計語言都有自己的語法，必須學習。"}]', '{"adjective":"syntactic","adverb":"syntactically"}', NULL, 2, 6403, NULL),
(6404, 'synthesize', '/ˈsɪnθəsaɪz/', 'verb', '{"zh-TW":["綜合；合成"],"en":["to combine elements into a coherent whole"]}', NULL, 'synthesize information / synthesize findings / synthesize data', '[{"en":"The review synthesizes evidence from fifty studies.","zh-TW":"該綜述綜合了五十項研究的證據。"},{"en":"She synthesized the two competing theories into a unified model.","zh-TW":"她將兩個競爭理論綜合成一個統一模型。"}]', '{"noun":"synthesis","adjective":"synthetic"}', NULL, 4, 6404, NULL),
(6405, 'synthetic', '/sɪnˈθetɪk/', 'adjective', '{"zh-TW":["合成的；人造的"],"en":["made by chemical synthesis; not natural"]}', NULL, 'synthetic materials / synthetic fibers / synthetic data', '[{"en":"The jacket is made of synthetic fibers.","zh-TW":"這件夾克是用合成纖維製成的。"},{"en":"Synthetic data is used to train AI models.","zh-TW":"合成數據被用來訓練AI模型。"}]', '{"noun":"synthesis","adjective":"synthetic","verb":"synthesize"}', NULL, 3, 6405, NULL),
(6406, 'system', '/ˈsɪstəm/', 'noun', '{"zh-TW":["系統；體系"],"en":["a set of connected things forming a complex whole"]}', NULL, 'operating system / system failure / management system', '[{"en":"The new IT system improves efficiency.","zh-TW":"新的資訊系統提高了效率。"},{"en":"We implemented a quality management system.","zh-TW":"我們實施了品質管理系統。"}]', '{"noun":"system","adjective":"systematic, systemic","adverb":"systematically"}', NULL, 2, 6406, 467),
(6407, 'system administrator', '/ˈsɪstəm ədˈmɪnɪstreɪtər/', 'noun', '{"zh-TW":["系統管理員"],"en":["a person responsible for maintaining computer systems"]}', NULL, 'contact the system administrator / experienced system administrator', '[{"en":"The system administrator set up the new employee accounts.","zh-TW":"系統管理員設置了新員工的帳號。"},{"en":"Report technical issues to the system administrator.","zh-TW":"向系統管理員報告技術問題。"}]', '{"abbreviation":"sysadmin"}', NULL, 5, 6407, NULL),
(6408, 'systematic', 'ˌsɪstɪˈmætɪk', 'adjective', '{"zh-TW":["系統性的；有條理的","有計劃的"],"en":["following a planned system","methodical"]}', NULL, 'systematic approach/systematic review', '[{"en":"Use a systematic approach to problem-solving.","zh-TW":"使用系統性的方法解決問題。"}]', '{"adverb":"systematically"}', NULL, 4, 6408, NULL),
(6409, 'systematic risk', '/ˌsɪstəˈmætɪk rɪsk/', 'noun', '{"zh-TW":["系統性風險"],"en":["risk affecting the entire market or economy, not just one company"]}', NULL, 'manage systematic risk / exposed to systematic risk', '[{"en":"Diversification cannot eliminate systematic risk.","zh-TW":"多元化無法消除系統性風險。"},{"en":"Interest rate changes are a major source of systematic risk.","zh-TW":"利率變化是系統性風險的主要來源。"}]', NULL, NULL, 5, 6409, NULL),
(6410, 'systemic', '/sɪˈstemɪk/', 'adjective', '{"zh-TW":["系統性的；全身性的"],"en":["relating to a system as a whole; deeply embedded in a system"]}', NULL, 'systemic change / systemic racism / systemic failure', '[{"en":"Systemic reforms are needed to address deep-rooted structural inequalities.","zh-TW":"需要進行系統性改革以解決根深蒂固的結構性不平等。"},{"en":"The financial crisis revealed systemic weaknesses in banking regulation.","zh-TW":"金融危機揭示了銀行監管方面的系統性弱點。"}]', '{"adverb":"systemically"}', NULL, 3, 6410, NULL),
(6411, 'systemic bias', '/sɪˈstemɪk baɪəs/', 'noun', '{"zh-TW":["系統性偏見"],"en":["prejudice embedded in institutional processes and outcomes rather than individual actions"]}', NULL, 'address systemic bias / evidence of systemic bias / overcome systemic bias', '[{"en":"Systemic bias in hiring practices disadvantages qualified candidates from underrepresented groups.","zh-TW":"招聘實踐中的系統性偏見使來自代表性不足群體的合格候選人處於不利地位。"},{"en":"Algorithms trained on biased data can perpetuate and amplify systemic bias.","zh-TW":"在有偏見的數據上訓練的算法可能會延續和放大系統性偏見。"}]', NULL, NULL, 5, 6411, NULL),
(6412, 'systemic inequality', '/sɪˈstemɪk ɪnˈiːkwəlɪti/', 'noun', '{"zh-TW":["系統性不平等"],"en":["inequality embedded in institutions and social structures rather than individual choices"]}', NULL, 'address systemic inequality / perpetuate systemic inequality / overcome systemic inequality', '[{"en":"Systemic inequality in education limits economic opportunities for disadvantaged communities.","zh-TW":"教育中的系統性不平等限制了弱勢社區的經濟機會。"},{"en":"Policy reform is needed to dismantle the structures that perpetuate systemic inequality.","zh-TW":"需要政策改革來拆除維持系統性不平等的結構。"}]', NULL, NULL, 5, 6412, NULL),
(6413, 'systemic risk', '/sɪˈstemɪk rɪsk/', 'noun', '{"zh-TW":["系統性風險"],"en":["risk affecting the entire market or economy, not just individual entities"]}', NULL, 'manage systemic risk / systemic risk assessment / reduce systemic risk', '[{"en":"The collapse of major banks creates systemic risk for the entire financial system.","zh-TW":"主要銀行倒閉為整個金融系統創造了系統性風險。"},{"en":"Regulators monitor systemic risk to prevent cascading financial failures.","zh-TW":"監管機構監測系統性風險以防止連鎖金融失敗。"}]', '{"adjective":"systemic","adverb":"systemically"}', NULL, 5, 6413, NULL),
(6414, 'table', '/ˈteɪbəl/', 'noun', '{"zh-TW":["【主要意義-名詞】桌子；表格","【次要意義-動詞（英式）】提出討論；將議題列入議程","【次要意義-動詞（美式）】擱置；延後討論"],"en":["[primary - noun] a piece of furniture with a flat top","[secondary - verb (British English)] to present something for discussion","[secondary - verb (American English)] to postpone discussion of something"]}', NULL, 'table a motion / table a proposal / table a discussion', '[{"en":"The committee tabled the budget proposal until next month. (AmE)","zh-TW":"委員會將預算提案延後到下個月討論。（美式）"},{"en":"The union tabled new wage demands at the meeting. (BrE)","zh-TW":"工會在會議上提出了新的薪資要求。（英式）"},{"en":"The issue was tabled for further review by the board.","zh-TW":"該議題被董事會擱置以供進一步審查。"}]', '{"noun":"tabling"}', '動詞 table 在美式和英式英語中意思相反！美式表示「擱置」，英式表示「提出」，TOEIC 考試以美式英語為主，此動詞常讓考生困惑。', 2, 6414, NULL),
(6415, 'tablet', '/ˈtæblɪt/', 'noun', '{"zh-TW":["平板電腦"],"en":["a flat portable computer with a touchscreen"]}', NULL, 'tablet computer / tablet screen', '[{"en":"She reads books on her tablet.","zh-TW":"她用平板電腦看書。"},{"en":"Tablets are popular for online learning.","zh-TW":"平板電腦在線上學習中很受歡迎。"}]', NULL, NULL, 2, 6415, NULL),
(6416, 'tabloid', '/ˈtæblɔɪd/', 'noun', '{"zh-TW":["小報；通俗報紙"],"en":["a newspaper with small pages and stories about entertainment and scandal"]}', NULL, 'tabloid journalism / tabloid headline / tabloid press', '[{"en":"The tabloid ran a sensationalized story about the celebrity''s private life.","zh-TW":"這份小報刊登了一篇關於名人私生活的聳人聽聞報道。"},{"en":"Tabloid journalism often prioritizes entertainment over factual reporting.","zh-TW":"小報新聞業通常將娛樂性置於事實報道之上。"}]', '{"adjective":"tabloid"}', NULL, 3, 6416, NULL),
(6417, 'tacit', '/ˈtæsɪt/', 'adjective', '{"zh-TW":["默示的；心照不宣的"],"en":["understood or implied without being stated directly"]}', NULL, 'tacit approval / tacit agreement / tacit knowledge', '[{"en":"His silence was interpreted as tacit consent to the proposed changes.","zh-TW":"他的沉默被解讀為對擬議變更的默示同意。"},{"en":"Tacit knowledge is difficult to transfer because it exists within individuals'' experience.","zh-TW":"默示知識難以轉移，因為它存在於個人的經驗之中。"}]', '{"adverb":"tacitly","noun":"tacitness"}', NULL, 2, 6417, NULL),
(6418, 'tacit knowledge', '/ˈtæsɪt ˈnɒlɪdʒ/', 'noun', '{"zh-TW":["默會知識；隱性知識"],"en":["knowledge gained through personal experience that is difficult to formalize or communicate to others"]}', NULL, 'share tacit knowledge / transfer tacit knowledge / benefit of tacit knowledge', '[{"en":"Tacit knowledge held by experienced employees is often lost when they retire.","zh-TW":"經驗豐富的員工所持有的默會知識往往在他們退休時流失。"},{"en":"Mentoring programs help transfer tacit knowledge from senior to junior staff.","zh-TW":"輔導計劃幫助將默會知識從資深員工傳遞給初級員工。"}]', '{"adjective":"tacit"}', NULL, 5, 6418, NULL),
(6419, 'tackle', '/ˈtækl/', 'verb, noun', '{"zh-TW":["處理；解決","應對"],"en":["to deal with a difficult problem","equipment or an act of confronting"]}', NULL, 'tackle a problem / tackle the issue / tackle challenges', '[{"en":"We must tackle the issue of rising costs.","zh-TW":"我們必須處理成本上漲的問題。"},{"en":"The team tackled the project head-on.","zh-TW":"團隊直接面對這個專案。"}]', '{"noun":"tackle","verb":"tackle"}', NULL, 2, 6419, NULL),
(6420, 'tactics', '/ˈtæktɪks/', 'noun', '{"zh-TW":["策略；戰術"],"en":["planned actions to achieve a specific end"]}', NULL, 'marketing tactics / negotiation tactics / change tactics', '[{"en":"The sales team adopted new marketing tactics.","zh-TW":"銷售團隊採用了新的行銷策略。"},{"en":"Aggressive tactics may backfire.","zh-TW":"激進的策略可能會適得其反。"}]', '{"noun":"tactics, tactician","adjective":"tactical","adverb":"tactically"}', NULL, 3, 6420, NULL),
(6421, 'tagline', '/ˈtæɡlaɪn/', 'noun', '{"zh-TW":["廣告語；標語"],"en":["a short memorable phrase associated with a brand or product"]}', NULL, 'create a tagline / memorable tagline / brand tagline', '[{"en":"Their tagline ''Just Do It'' is one of the most recognized in the world.","zh-TW":"他們的廣告語「Just Do It」是世界上最知名的之一。"},{"en":"The new tagline better reflected the brand''s commitment to innovation.","zh-TW":"新標語更好地反映了品牌對創新的承諾。"}]', '{"alternative":"slogan"}', NULL, 3, 6421, NULL),
(6422, 'tail risk', '/teɪl rɪsk/', 'noun', '{"zh-TW":["尾部風險"],"en":["the risk of an unlikely but extreme event causing significant losses"]}', NULL, 'manage tail risk / hedge against tail risk', '[{"en":"The portfolio was structured to protect against tail risk scenarios.","zh-TW":"投資組合的結構旨在防範尾部風險情境。"},{"en":"Tail risk events like financial crises are rare but devastating.","zh-TW":"金融危機等尾部風險事件雖罕見但破壞力極強。"}]', NULL, NULL, 3, 6422, NULL),
(6423, 'tailor', '/ˈteɪlər/', 'verb, noun', '{"zh-TW":["量身定做；裁剪","裁縫"],"en":["to make or adapt for a particular purpose","a person who makes clothes"]}', NULL, 'tailor-made / tailor to needs / tailor a solution', '[{"en":"We can tailor our services to your needs.","zh-TW":"我們可以根據您的需求量身定制服務。"},{"en":"The training program is tailored for new employees.","zh-TW":"培訓計畫是為新員工量身定制的。"}]', '{"noun":"tailor","verb":"tailor","adjective":"tailored"}', NULL, 2, 6423, NULL),
(6424, 'take', '/teɪk/', 'verb', '{"zh-TW":["拿；花費；採取"],"en":["to carry","to require time","to perform an action"]}', NULL, 'take action / take place', '[{"en":"We need to take action immediately.","zh-TW":"我們需要立即採取行動。"},{"en":"The conference takes place in March.","zh-TW":"會議在三月舉行。"}]', '{"verb":"take","noun":"takeover","noun2":"intake"}', NULL, 1, 6424, NULL),
(6425, 'take precedence', '/''teɪk ˌpresɪdəns/', 'phrase', '{"zh-TW":["優先；居首位"],"en":["to be more important than something else and therefore be dealt with or considered first"]}', NULL, 'take precedence over / take clear precedence / take legal precedence', '[{"en":"Safety always takes precedence over speed in our manufacturing processes.","zh-TW":"在我們的製造過程中，安全始終優先於速度。"},{"en":"Client needs take precedence over internal preferences when making product decisions.","zh-TW":"在做出產品決策時，客戶需求優先於內部偏好。"}]', NULL, NULL, 5, 6425, NULL),
(6426, 'take-or-pay contract', '/teɪk ɔːr peɪ ˈkɒntrækt/', 'noun', '{"zh-TW":["照付不議合約"],"en":["an agreement requiring the buyer to pay even if they do not take delivery"]}', NULL, 'sign a take-or-pay contract / take-or-pay contract terms', '[{"en":"The gas utility signed a take-or-pay contract for 10 years.","zh-TW":"燃氣公司簽署了一份10年的照付不議合約。"},{"en":"Take-or-pay contracts provide stable revenue for suppliers.","zh-TW":"照付不議合約為供應商提供了穩定的收入。"}]', NULL, NULL, 5, 6426, NULL),
(6427, 'takeout', '/ˈteɪkaʊt/', 'noun', '{"zh-TW":["外帶；外賣"],"en":["food ordered from a restaurant to eat elsewhere"]}', NULL, 'order takeout / takeout menu', '[{"en":"We ordered takeout because we were too tired to cook.","zh-TW":"我們因為太累而訂了外賣。"},{"en":"The restaurant offers a takeout service from 11 am.","zh-TW":"餐廳從上午11點提供外賣服務。"}]', NULL, NULL, 3, 6427, NULL),
(6428, 'takeover', '/ˈteɪkˌoʊvər/', 'noun', '{"zh-TW":["接管；收購"],"en":["gaining control of a company by purchasing its shares"]}', NULL, 'hostile takeover / takeover bid / takeover defense', '[{"en":"The hostile takeover was rejected by the board.","zh-TW":"敵意收購被董事會拒絕了。"},{"en":"A takeover bid was launched at a 30% premium.","zh-TW":"以30%的溢價發起了收購要約。"}]', '{"verb":"take over"}', NULL, 3, 6428, NULL),
(6429, 'takeover bid', '/ˈteɪkoʊvər bɪd/', 'noun', '{"zh-TW":["收購要約"],"en":["a formal offer to purchase enough shares to gain control of a company"]}', NULL, 'launch a takeover bid / reject a takeover bid', '[{"en":"The board rejected the hostile takeover bid as undervaluing the company.","zh-TW":"董事會以低估公司價值為由拒絕了敵意收購要約。"},{"en":"A friendly takeover bid results in agreed terms between both boards.","zh-TW":"友好的收購要約在雙方董事會之間達成了商定條款。"}]', '{"synonym":"acquisition bid"}', NULL, 4, 6429, NULL),
(6430, 'talent', '/ˈtælənt/', 'noun', '{"zh-TW":["人才；才能"],"en":["natural aptitude; skilled people"]}', NULL, 'talent pool / talent acquisition / talented employees', '[{"en":"The company invests heavily in talent acquisition.","zh-TW":"公司大力投資人才招募。"},{"en":"Retaining top talent is a key challenge.","zh-TW":"留住頂尖人才是主要的挑戰。"}]', '{"noun":"talent","adjective":"talented"}', NULL, 2, 6430, NULL),
(6431, 'talent acquisition', '/ˈtælənt ˌækwɪˈzɪʃən/', 'noun', '{"zh-TW":["人才招募；人才獲取"],"en":["the process of finding and hiring skilled employees"]}', NULL, 'lead talent acquisition / talent acquisition strategy', '[{"en":"Talent acquisition is a top priority for growing companies.","zh-TW":"人才招募對於成長中的公司是首要任務。"},{"en":"She heads the talent acquisition team for the Asia region.","zh-TW":"她負責亞洲地區的人才招募團隊。"}]', NULL, NULL, 5, 6431, NULL),
(6432, 'talent development', '/''tælənt dɪˌveləpmənt/', 'noun', '{"zh-TW":["人才培育；人才發展"],"en":["the process of identifying and nurturing the skills and abilities of employees"]}', NULL, 'invest in talent development / talent development program / talent development strategy', '[{"en":"Companies that invest in talent development tend to have more motivated and productive employees.","zh-TW":"投資人才培育的公司往往擁有更有積極性和更高生產力的員工。"},{"en":"Her talent development plan included mentoring, training, and stretch assignments.","zh-TW":"她的人才發展計劃包括指導、培訓和挑戰性任務。"}]', NULL, NULL, 5, 6432, NULL),
(6433, 'talent management', '/ˈtælənt ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["人才管理"],"en":["attracting, developing, and retaining skilled employees"]}', NULL, 'talent management strategy / talent management system', '[{"en":"Effective talent management reduces costly employee turnover.","zh-TW":"有效的人才管理可減少代價高昂的員工流動。"},{"en":"The firm invested heavily in talent management programs.","zh-TW":"公司在人才管理計劃上投入了大量資金。"}]', '{"verb":"manage talent"}', NULL, 5, 6433, NULL),
(6434, 'talent pipeline', '/ˈtælənt ˈpaɪplaɪn/', 'noun', '{"zh-TW":["人才梯隊；人才儲備"],"en":["a pool of qualified candidates ready to fill future openings"]}', NULL, 'build a talent pipeline / talent pipeline management / maintain a talent pipeline', '[{"en":"Building a strong talent pipeline reduces time-to-hire.","zh-TW":"建立強大的人才梯隊可以縮短招聘時間。"},{"en":"The company''s talent pipeline ensures leadership continuity.","zh-TW":"公司的人才梯隊確保了領導層的連續性。"}]', NULL, NULL, 5, 6434, NULL),
(6435, 'talk', '/tɔːk/', 'verb', '{"zh-TW":["說話；談論"],"en":["to speak","to discuss"]}', NULL, 'talk about / small talk', '[{"en":"Let''s talk about the budget.","zh-TW":"我們來談談預算。"},{"en":"He gave a talk on leadership.","zh-TW":"他做了一場關於領導力的演講。"}]', '{"verb":"talk","noun":"talk","noun2":"talker"}', NULL, 1, 6435, NULL),
(6436, 'talking points', '/ˈtɔːkɪŋ pɔɪnts/', 'noun', '{"zh-TW":["談話要點；發言重點"],"en":["key points prepared in advance for a meeting or speech"]}', NULL, 'prepare talking points / key talking points', '[{"en":"He prepared talking points before the media interview.","zh-TW":"他在媒體採訪前準備了談話要點。"},{"en":"Share talking points with the team before client meetings.","zh-TW":"在客戶會議前與團隊分享發言重點。"}]', NULL, NULL, 5, 6436, NULL),
(6437, 'tangential', '/tænˈdʒentʃəl/', 'adjective', '{"zh-TW":["切線的；不相關的"],"en":["diverging from a previous course; only slightly relevant"]}', NULL, 'tangential argument / tangential remark / tangential issue', '[{"en":"The comment was tangential to the main topic of discussion.","zh-TW":"這個評論與討論的主要話題只有切線關聯。"},{"en":"Avoid tangential points that distract from your core argument.","zh-TW":"避免分散注意力的不相關論點。"}]', '{"adverb":"tangentially"}', NULL, 4, 6437, NULL),
(6438, 'tangible', '/ˈtændʒəbl/', 'adjective', '{"zh-TW":["有形的；實際的"],"en":["clear and definite; able to be touched"]}', NULL, 'tangible results / tangible assets / tangible benefits', '[{"en":"The training produced tangible results.","zh-TW":"培訓產生了實際的成果。"},{"en":"Tangible assets include buildings and equipment.","zh-TW":"有形資產包括建築物和設備。"}]', '{"noun":"tangibility","adjective":"tangible, intangible"}', NULL, 3, 6438, 940),
(6439, 'tangible asset', '/ˈtændʒɪbəl ˈæset/', 'noun', '{"zh-TW":["有形資產"],"en":["a physical asset such as property, equipment, or inventory"]}', NULL, 'value tangible assets / tangible asset base', '[{"en":"The company strong tangible asset base supports its borrowing capacity.","zh-TW":"公司強大的有形資產基礎支持其借貸能力。"},{"en":"Tangible assets are easier to value than intangible ones.","zh-TW":"有形資產比無形資產更容易估值。"}]', '{"plural":"tangible assets","opposite":"intangible asset"}', NULL, 5, 6439, NULL),
(6440, 'target', '/ˈtɑːrɡɪt/', 'noun, verb', '{"zh-TW":["目標；對象","以...為目標"],"en":["an aim or objective","to direct at a particular group"]}', NULL, 'target market / target audience / meet the target', '[{"en":"We exceeded our sales target by 10%.","zh-TW":"我們超額完成了10%的銷售目標。"},{"en":"The campaign targets young professionals.","zh-TW":"該活動以年輕專業人士為目標對象。"}]', '{"noun":"target","verb":"target","adjective":"targeted"}', NULL, 2, 6440, 228),
(6441, 'target audience', '/ˈtɑːrɡɪt ˈɔːdiəns/', 'noun', '{"zh-TW":["目標受眾；目標群體"],"en":["the specific group of people a marketing campaign is aimed at"]}', NULL, 'define the target audience / reach the target audience', '[{"en":"The ad campaign was tailored to the target audience of young professionals.","zh-TW":"廣告活動專為年輕專業人士的目標受眾量身定制。"},{"en":"Understanding your target audience is the foundation of good marketing.","zh-TW":"了解您的目標受眾是良好行銷的基礎。"}]', NULL, NULL, 5, 6441, NULL),
(6442, 'target market', '/ˈtɑːrɡɪt ˈmɑːrkɪt/', 'noun', '{"zh-TW":["目標市場"],"en":["the specific group of consumers a product or service is aimed at"]}', NULL, 'define your target market / reach your target market / niche target market', '[{"en":"The campaign was designed specifically for our target market of young professionals.","zh-TW":"該活動專門為我們的年輕專業人士目標市場設計。"},{"en":"Understanding your target market is the foundation of marketing strategy.","zh-TW":"了解目標市場是行銷策略的基礎。"}]', '{"verb":"target"}', NULL, 5, 6442, NULL),
(6443, 'target setting', '/ˈtɑːrɡɪt ˈsetɪŋ/', 'noun', '{"zh-TW":["目標設定"],"en":["the process of defining measurable goals for individuals or teams"]}', NULL, 'improve target setting / target setting process', '[{"en":"The target setting process aligns team goals with company objectives.","zh-TW":"目標設定流程使團隊目標與公司目標保持一致。"},{"en":"Realistic target setting motivates employees without creating undue pressure.","zh-TW":"現實的目標設定在不造成過度壓力的情況下激勵員工。"}]', NULL, NULL, 5, 6443, NULL),
(6444, 'targeted', 'ˈtɑːrɡɪtɪd', 'adjective', '{"zh-TW":["針對性的；定向的","有目標的"],"en":["aimed at a specific group","focused"]}', NULL, 'targeted campaign/targeted approach', '[{"en":"We use targeted marketing campaigns.","zh-TW":"我們使用定向行銷活動。"}]', '{"verb":"target","noun":"target"}', NULL, 3, 6444, NULL),
(6445, 'tariff', '/ˈtærɪf/', 'noun', '{"zh-TW":["關稅；稅率"],"en":["a tax on imported or exported goods"]}', NULL, 'import tariff / tariff barriers / impose tariffs', '[{"en":"The government imposed tariffs on imported steel.","zh-TW":"政府對進口鋼材徵收關稅。"},{"en":"Tariff reductions boosted international trade.","zh-TW":"關稅降低促進了國際貿易。"}]', '{"noun":"tariff"}', NULL, 2, 6445, NULL),
(6446, 'task', '/tæsk/', 'noun', '{"zh-TW":["任務；工作"],"en":["a piece of work to be done"]}', NULL, 'complete a task / task management / assign a task', '[{"en":"The manager assigned tasks to each team member.","zh-TW":"經理給每位團隊成員分配了任務。"},{"en":"Completing this task is our top priority.","zh-TW":"完成這項任務是我們的首要目標。"}]', '{"noun":"task","verb":"task"}', NULL, 1, 6446, 229),
(6447, 'task delegation', '/tæsk ˌdɛlɪˈɡeɪʃən/', 'noun', '{"zh-TW":["任務委派"],"en":["the assignment of tasks to others"]}', NULL, 'effective task delegation / practice task delegation', '[{"en":"Effective task delegation allows managers to focus on strategy.","zh-TW":"有效的任務委派允許管理者專注於策略。"},{"en":"She improved team productivity through smart task delegation.","zh-TW":"她透過聰明的任務委派提高了團隊生產力。"}]', NULL, NULL, 5, 6447, NULL),
(6448, 'task force', '/tæsk fɔːrs/', 'noun', '{"zh-TW":["特別工作組；專案小組"],"en":["a temporary group formed to tackle a specific problem or project"]}', NULL, 'set up a task force / lead a task force / task force report / task force recommendation', '[{"en":"A task force was formed to address the supply chain disruptions.","zh-TW":"成立了一個特別工作組以應對供應鏈中斷問題。"},{"en":"The task force delivered its recommendations within 30 days.","zh-TW":"特別工作組在30天內提交了建議。"}]', '{"plural":"task forces"}', NULL, 4, 6448, NULL),
(6449, 'tasting menu', '/ˈteɪstɪŋ ˈmɛnjuː/', 'noun', '{"zh-TW":["試菜菜單；品嚐套餐"],"en":["a series of small dishes to sample a chef''s cooking"]}', NULL, 'order the tasting menu / tasting menu experience', '[{"en":"The tasting menu features eight courses of seasonal dishes.","zh-TW":"試菜菜單包含八道時令菜餚。"},{"en":"We opted for the tasting menu to try more dishes.","zh-TW":"我們選擇了試菜菜單以品嚐更多菜餚。"}]', NULL, NULL, 4, 6449, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(6450, 'tax', '/tæks/', 'noun, verb', '{"zh-TW":["稅；稅金","課稅"],"en":["a compulsory payment to the government","to impose a tax on"]}', NULL, 'income tax / tax return / tax deduction', '[{"en":"The new tax policy benefits small businesses.","zh-TW":"新的稅務政策有利於小型企業。"},{"en":"Corporate profits are taxed at 20%.","zh-TW":"企業利潤按20%的稅率課稅。"}]', '{"noun":"tax, taxation, taxpayer","verb":"tax","adjective":"taxable"}', NULL, 1, 6450, NULL),
(6451, 'tax avoidance', '/tæks əˈvɔɪdəns/', 'noun', '{"zh-TW":["避稅"],"en":["legally minimizing tax liability through allowable means"]}', NULL, 'engage in tax avoidance / legal tax avoidance', '[{"en":"Tax avoidance using legitimate strategies reduces the company tax bill.","zh-TW":"使用合法策略避稅降低了公司的稅務賬單。"},{"en":"There is a fine line between tax avoidance and tax evasion.","zh-TW":"避稅和逃稅之間只有一線之差。"}]', NULL, NULL, 5, 6451, NULL),
(6452, 'tax base', '/tæks beɪs/', 'noun', '{"zh-TW":["稅基"],"en":["the total amount of assets or income subject to taxation"]}', NULL, 'broaden the tax base / tax base erosion', '[{"en":"Broadening the tax base allows governments to lower individual rates.","zh-TW":"擴大稅基允許政府降低個人稅率。"},{"en":"Multinational companies have been accused of eroding the domestic tax base.","zh-TW":"跨國公司被指控侵蝕國內稅基。"}]', NULL, NULL, 3, 6452, NULL),
(6453, 'tax credit', '/tæks ˈkredɪt/', 'noun', '{"zh-TW":["稅收抵免"],"en":["a direct reduction in the amount of tax owed"]}', NULL, 'claim a tax credit / research and development tax credit', '[{"en":"The company claimed an R&D tax credit for its innovation program.","zh-TW":"公司為其創新計劃申請了研發稅收抵免。"},{"en":"A tax credit directly reduces the amount of tax owed.","zh-TW":"稅收抵免直接減少應繳稅款。"}]', NULL, NULL, 4, 6453, NULL),
(6454, 'tax deduction', '/tæks dɪˈdʌkʃən/', 'noun', '{"zh-TW":["稅務扣除；抵稅項目"],"en":["an expense that can be subtracted from taxable income to reduce tax liability"]}', NULL, 'claim a tax deduction / tax deduction for business expenses', '[{"en":"Business travel expenses are eligible for a tax deduction.","zh-TW":"商務旅行費用可申請稅務扣除。"},{"en":"She claimed a tax deduction for her home office expenses.","zh-TW":"她申請了家庭辦公室費用的稅務扣除。"}]', '{"verb":"deduct","adjective":"tax-deductible"}', NULL, 5, 6454, NULL),
(6455, 'tax efficiency', '/tæks ɪˈfɪʃənsi/', 'noun', '{"zh-TW":["稅務效率"],"en":["minimizing the tax burden through legal planning and structure"]}', NULL, 'improve tax efficiency / tax-efficient structure', '[{"en":"The corporate structure was designed for tax efficiency.","zh-TW":"企業結構被設計為稅務效率最優。"},{"en":"Tax efficiency is a key consideration in cross-border investment.","zh-TW":"稅務效率是跨境投資的重要考量因素。"}]', '{"adjective":"tax-efficient"}', NULL, 5, 6455, NULL),
(6456, 'tax evasion', '/tæks ɪˈveɪʒən/', 'noun', '{"zh-TW":["逃稅"],"en":["the illegal non-payment or underpayment of taxes"]}', NULL, 'commit tax evasion / investigate tax evasion / charged with tax evasion', '[{"en":"Tax evasion through offshore accounts costs governments billions in revenue annually.","zh-TW":"通過離岸帳戶逃稅每年使政府損失數十億的稅收收入。"},{"en":"The businessman was prosecuted for tax evasion after a forensic audit uncovered hidden income.","zh-TW":"在法證審計發現隱藏收入後，這位商人因逃稅被起訴。"}]', NULL, NULL, 4, 6456, NULL),
(6457, 'tax exemption', '/tæks ɪɡˈzempʃən/', 'noun', '{"zh-TW":["免稅；稅收豁免"],"en":["a legal reduction or elimination of tax liability granted by a government"]}', NULL, 'apply for a tax exemption / qualify for a tax exemption', '[{"en":"The nonprofit organization applied for a tax exemption on its income.","zh-TW":"非牟利組織申請了其收入的稅收豁免。"},{"en":"Special economic zones offer tax exemptions to attract foreign investment.","zh-TW":"特殊經濟區提供稅收豁免以吸引外資。"}]', '{"verb":"exempt from tax"}', NULL, 5, 6457, NULL),
(6458, 'tax expense', '/tæks ɪkˈspens/', 'noun', '{"zh-TW":["稅務費用"],"en":["the amount of income taxes owed or accrued by a company"]}', NULL, 'calculate tax expense / current tax expense', '[{"en":"Tax expense reduced net profit by $2 million this year.","zh-TW":"稅務費用今年使淨利潤減少了200萬美元。"},{"en":"Deferred tax affects the total tax expense reported in the accounts.","zh-TW":"遞延稅影響帳目中報告的總稅務費用。"}]', NULL, NULL, 4, 6458, NULL),
(6459, 'tax haven', '/tæks ˈheɪvən/', 'noun', '{"zh-TW":["避稅天堂"],"en":["a country or territory with very low tax rates that attracts foreign businesses"]}', NULL, 'use a tax haven / offshore tax haven / crack down on tax havens', '[{"en":"Multinationals route profits through tax havens to reduce their overall tax burden.","zh-TW":"跨國公司將利潤通過避稅天堂轉移，以減少整體稅務負擔。"},{"en":"International efforts to curb tax havens have had limited success due to sovereignty issues.","zh-TW":"由於主權問題，限制避稅天堂的國際努力收效甚微。"}]', NULL, NULL, 3, 6459, NULL),
(6460, 'tax incentive', '/tæks ɪnˈsentɪv/', 'noun', '{"zh-TW":["稅收優惠"],"en":["a reduction in tax designed to encourage certain business activities"]}', NULL, 'offer a tax incentive / tax incentive for investment', '[{"en":"The government offered a tax incentive to firms investing in green energy.","zh-TW":"政府為投資綠色能源的公司提供了稅收優惠。"},{"en":"Tax incentives for R&D spending have increased innovation activity.","zh-TW":"研發支出的稅收優惠增加了創新活動。"}]', NULL, NULL, 5, 6460, NULL),
(6461, 'tax incidence', '/tæks ˈɪnsɪdəns/', 'noun', '{"zh-TW":["稅負歸宿；稅收歸宿"],"en":["the analysis of who ultimately bears the economic burden of a tax"]}', NULL, 'tax incidence analysis / tax incidence theory / corporate tax incidence', '[{"en":"Tax incidence shows that a corporate tax may ultimately be borne by workers through lower wages.","zh-TW":"稅負歸宿分析表明，企業稅最終可能通過較低工資由工人承擔。"},{"en":"The tax incidence depends on the relative elasticity of supply and demand.","zh-TW":"稅收歸宿取決於供求的相對彈性。"}]', NULL, NULL, 5, 6461, NULL),
(6462, 'tax liability', '/tæks laɪəˈbɪlɪti/', 'noun', '{"zh-TW":["稅務負債；應付稅款"],"en":["the total amount of tax owed to the government"]}', NULL, 'calculate tax liability / reduce tax liability', '[{"en":"The company''s tax liability was reduced through allowable deductions.","zh-TW":"公司的稅務負債通過允許的扣除額降低了。"},{"en":"Deferred tax liability arises when income is taxed at a future date.","zh-TW":"遞延稅務負債在收入在未來日期被徵稅時產生。"}]', NULL, NULL, 5, 6462, NULL),
(6463, 'tax loss carryforward', '/tæks lɒs ˈkærifɔːrwərd/', 'noun', '{"zh-TW":["虧損結轉"],"en":["the use of a current year''s tax loss to offset future year''s taxable income"]}', NULL, 'apply a tax loss carryforward / tax loss carryforward benefit', '[{"en":"The company used a tax loss carryforward to reduce next year''s tax.","zh-TW":"公司使用了虧損結轉來減少明年的稅款。"},{"en":"Tax loss carryforwards can significantly reduce future tax liabilities.","zh-TW":"虧損結轉可以顯著降低未來的稅務負債。"}]', NULL, NULL, 5, 6463, NULL),
(6464, 'tax planning', '/tæks ˈplænɪŋ/', 'noun', '{"zh-TW":["稅務規劃"],"en":["organizing finances to legally minimize tax obligations"]}', NULL, 'engage in tax planning / tax planning strategy', '[{"en":"The accountant provided tax planning advice for the year ahead.","zh-TW":"會計師為未來一年提供了稅務規劃建議。"},{"en":"Proactive tax planning can significantly reduce the annual tax bill.","zh-TW":"主動的稅務規劃可以顯著降低年度稅務帳單。"}]', NULL, NULL, 4, 6464, NULL),
(6465, 'tax relief', '/tæks rɪˈliːf/', 'noun', '{"zh-TW":["稅務減免；稅收優惠"],"en":["a reduction in the amount of tax a person or company must pay"]}', NULL, 'claim tax relief / qualify for tax relief', '[{"en":"Small businesses can claim tax relief on new equipment purchases.","zh-TW":"小企業可以就新設備採購申請稅務減免。"},{"en":"Tax relief for charitable donations encourages corporate philanthropy.","zh-TW":"慈善捐款的稅務減免鼓勵了企業慈善事業。"}]', NULL, NULL, 4, 6465, NULL),
(6466, 'tax return', '/tæks rɪˈtɜːrn/', 'noun', '{"zh-TW":["稅務申報表"],"en":["a form filed with a tax authority reporting income and taxes owed"]}', NULL, 'file a tax return / annual tax return / corporate tax return', '[{"en":"The company filed its corporate tax return before the April deadline.","zh-TW":"公司在四月截止日期前提交了企業稅務申報表。"},{"en":"Tax returns must be accurate to avoid penalties from the tax authority.","zh-TW":"稅務申報表必須準確，以避免稅務機關的罰款。"}]', NULL, NULL, 4, 6466, NULL),
(6467, 'tax shield', '/tæks ʃiːld/', 'noun', '{"zh-TW":["稅盾；稅收優惠"],"en":["a reduction in taxable income through allowable deductions"]}', NULL, 'interest tax shield / depreciation tax shield / tax shield benefit', '[{"en":"Debt financing creates a tax shield through deductible interest payments.","zh-TW":"債務融資通過可扣除的利息支付創造稅盾。"},{"en":"Companies leverage the tax shield of depreciation to reduce their tax burden.","zh-TW":"公司利用折舊稅盾來減少稅收負擔。"}]', NULL, NULL, 4, 6467, NULL),
(6468, 'taxi rank', '/ˈtæksi ræŋk/', 'noun', '{"zh-TW":["計程車站"],"en":["a designated place where taxis wait for passengers"]}', NULL, 'wait at the taxi rank / taxi rank outside the terminal', '[{"en":"There is a taxi rank just outside the arrivals terminal.","zh-TW":"入境大廳外面就有計程車站。"},{"en":"The taxi rank was very busy after the conference ended.","zh-TW":"會議結束後計程車站非常繁忙。"}]', NULL, NULL, 3, 6468, NULL),
